import{_ as a,c as t,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const p=JSON.parse('{"title":"Node.js — runtime to backend services","description":"A Node.js runtime course with explicit backend, database and deployment continuations.","frontmatter":{"title":"Node.js — runtime to backend services","description":"A Node.js runtime course with explicit backend, database and deployment continuations.","outline":"deep"},"headers":[],"relativePath":"node-js/index.md","filePath":"node-js/index.md"}'),s={name:"node-js/index.md"};function i(o,e,d,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="node-js-runtime-to-backend-services" tabindex="-1">Node.js: runtime to backend services <a class="header-anchor" href="#node-js-runtime-to-backend-services" aria-label="Permalink to “Node.js: runtime to backend services”">​</a></h1><p><strong>Start with the runtime course.</strong> Express, databases, authentication and deployment are continuations, so you can learn Node.js without first building a complete full-stack product.</p><p>The material targets independent intermediate Node.js work: explain the runtime, implement a bounded program, diagnose common failures and own its resources. Selected service chapters go deeper into security and reliability. Finalized material and ready-to-use specifications do not establish completed learner practice or professional mastery.</p><h2 id="prerequisites-and-boundaries" tabindex="-1"><span class="hub-section-number">1 </span>Prerequisites and boundaries <a class="header-anchor" href="#prerequisites-and-boundaries" aria-label="Permalink to “1 Prerequisites and boundaries”">​</a></h2><p>You need JavaScript functions, scope/closures, arrays/objects, modules, basic promises and <code>try</code>/<code>catch</code>; basic terminal and package-manager use is enough to begin. TypeScript annotations describe contracts in many examples. See <a href="./module-01-nodejs-foundations.html#javascript-examples-and-typescript-examples">running the examples</a> before executing them.</p><p>The <a href="./prerequisites-and-boundaries.html">shared JavaScript references</a> fill specific prerequisite needs. Read them when needed rather than repeat a whole frontend track. Browser rendering, DOM workers and browser CORS enforcement are different host concerns; Node output is not evidence of a browser paint or cookie decision.</p><table tabindex="0"><thead><tr><th>Scope</th><th>Includes</th><th>Does not have to come first</th></tr></thead><tbody><tr><td>Core Node.js</td><td>Modules/npm/process, async execution, errors, files, bytes/streams, raw HTTP, cancellation/cleanup, testing and runtime diagnostics</td><td>Express, ORM, database, cloud or broker</td></tr><tr><td>Backend service continuation</td><td>Express/use cases, current authorization, API schemas, application lifecycle</td><td>Microservices or multiple alternative frameworks</td></tr><tr><td>Persistence continuation</td><td>PostgreSQL/SQL/MikroORM; constraints, transactions, migrations and query diagnosis</td><td>MongoDB or Redis</td></tr><tr><td>Delivery/distribution continuation</td><td>Containers, restore/rollback, durable jobs, operational failure boundaries</td><td>AWS/Kubernetes administration or a deployed multi-service system</td></tr></tbody></table><h2 id="recommended-reading-order" tabindex="-1"><span class="hub-section-number">2 </span>Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to “2 Recommended reading order”">​</a></h2><h3 id="runtime-foundations" tabindex="-1"><span class="hub-section-number">2.1 </span>Runtime foundations <a class="header-anchor" href="#runtime-foundations" aria-label="Permalink to “2.1 Runtime foundations”">​</a></h3><ul><li><a href="./module-01-nodejs-foundations.html">Foundations</a>: runtime, CJS/ESM, npm, scheduling, promises and bounded concurrency.</li><li><a href="./module-02-standard-library.html">Standard library</a>: errors, process/CLI, files/handles/paths, crypto and subprocess/worker ownership. Worker pools and cluster are later depth.</li><li><a href="./module-03-events-buffers-streams.html">Events, buffers and streams</a>: notifications, bytes/encoding, framing, backpressure, iteration and cleanup.</li><li><a href="./module-04-testing.html">Testing</a>: awaitable checks, useful assertions, controlled failures and open handles. Its database/E2E sections become relevant with a service.</li><li><a href="./module-05-networking.html">Networking</a>: raw HTTP, request/response streams, bounded clients, TLS/DNS, deadlines and security boundaries. REST architecture and real-time alternatives can follow your first server.</li><li><a href="./module-11-performance-diagnostics.html">Diagnostics</a>: measure event-loop behavior, resource ownership, memory categories and one reproducible bottleneck. Database pool diagnosis belongs with persistence.</li><li><a href="./module-10-production-ready-applications.html">Lifecycle</a>: use configuration, startup, safe diagnostics, readiness and shutdown for your first long-running server. Its deployment-specific sections are a continuation.</li></ul><p>Apply these in the <a href="./../practice/node-js/core-project.html">small log-analyzer project</a>, then deepen failure handling with <a href="./../practice/backend-project.html#p-332">P-332</a>. The <a href="./../practice/node-js/">chapter exercises</a> are separate from the explanations; every learner task remains outstanding until independently performed.</p><h3 id="one-backend-and-persistence-path" tabindex="-1"><span class="hub-section-number">2.2 </span>One backend and persistence path <a class="header-anchor" href="#one-backend-and-persistence-path" aria-label="Permalink to “2.2 One backend and persistence path”">​</a></h3><ul><li><a href="./module-06-express-architecture.html">Express and architecture</a>: ordered middleware, validation, use cases and persistence boundaries.</li><li><a href="./module-08-postgresql-mikroorm.html">PostgreSQL and MikroORM</a>: learn SQL/constraints before ORM behavior. The <a href="./../workbench/node-js/database/sql-queries.html">SQL workbench</a> supplies one coherent fixture.</li><li><a href="./module-09-authentication-authorization.html">Authentication and authorization</a>: sessions, CSRF, passwords, tokens and current owner/tenant policy. Its <a href="./../workbench/node-js/backend/session-app.html">runnable application reference</a> reuses existing source.</li><li>Return to <a href="./module-10-production-ready-applications.html">production lifecycle</a> and the database sections of <a href="./module-11-performance-diagnostics.html">diagnostics</a> for the integrated service.</li></ul><p><a href="./../practice/backend-project.html#p-331">P-331</a> is the ready-to-use integration specification. PostgreSQL/REST is the primary path; <a href="./module-07-mongodb-mongoose.html">MongoDB/Mongoose</a> is an optional document-model comparison.</p><h3 id="delivery-and-distributed-failure" tabindex="-1"><span class="hub-section-number">2.3 </span>Delivery and distributed failure <a class="header-anchor" href="#delivery-and-distributed-failure" aria-label="Permalink to “2.3 Delivery and distributed failure”">​</a></h3><ul><li><a href="./module-12-resilient-distributed-systems.html">Resilient/distributed systems</a>: unknown outcomes, duplicates, outbox, queues, caching and recovery. A modular monolith remains the starting point.</li><li><a href="./container-deployment-lab.html">Container deployment</a>, <a href="./database-recovery.html">backup/recovery</a>, <a href="./release-artifact-compatibility.html">release compatibility</a> and <a href="./full-stack-deployment.html">whole-stack local deployment</a> prepare <a href="./../practice/backend-project.html#p-333">P-333</a>. A fixture run is distinct from an authenticated hosted deployment.</li></ul><h2 id="supplements-by-requirement" tabindex="-1"><span class="hub-section-number">3 </span>Supplements by requirement <a class="header-anchor" href="#supplements-by-requirement" aria-label="Permalink to “3 Supplements by requirement”">​</a></h2><p>The sidebar groups these supplements into <strong>Backend and persistence continuation</strong> (database queries and calendar data), <strong>Security and data handling</strong> (uploads, deletion, callbacks and browser boundaries), and <strong>API transports and adapters</strong> (real-time updates, alternative APIs and shared cache/limits). Choose them when your service needs the capability; they are not additional runtime prerequisites.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Reading/reference</th></tr></thead><tbody><tr><td>Public API contract and drift</td><td><a href="./../workbench/node-js/backend/rest-contracts.html">REST/OpenAPI workbench</a></td></tr><tr><td>Ordered database feeds and calendar data</td><td><a href="./cursor-pagination.html">Cursor pagination</a>, <a href="./dates-and-time-zones.html">dates/time zones</a></td></tr><tr><td>Private bounded text ingress</td><td><a href="./safe-text-uploads.html">Uploads and multipart variant</a>, <a href="./retention-and-deletion.html">expiry/deletion</a></td></tr><tr><td>Provider callbacks</td><td><a href="./signed-webhooks.html">Signed webhooks</a></td></tr><tr><td>Browser document/login boundaries</td><td><a href="./browser-csp.html">CSP</a>, <a href="./oidc-and-csrf-lab.html">OIDC/CSRF alternatives</a></td></tr><tr><td>Real-time updates or alternative APIs</td><td><a href="./realtime-transports.html">SSE/polling/gRPC</a>, <a href="./graphql-basics.html">GraphQL</a></td></tr><tr><td>Shared cache/abuse limits</td><td><a href="./redis-adapters.html">Redis adapters</a></td></tr><tr><td>Durable work and schedules</td><td><a href="./jobs-and-schedules.html">Jobs/scheduling</a></td></tr><tr><td>Cloud architecture awareness</td><td><a href="./aws-service-slice.html">AWS slice</a>; Kubernetes awareness remains in the deployment continuation</td></tr></tbody></table><p>All substantial collections have a <a href="./../workbench/node-js/">workbench home</a>. It distinguishes runnable fixtures, composable source examples and adaptation templates with additional environment requirements. Project requirements, acceptance criteria and learner checklists live in <a href="./../practice/node-js/">practice</a>. Preserve any Autocode task&#39;s supplied build/Jest/database/coverage configuration and restricted tests. Only the user may push repository changes.</p><h2 id="node-js-tech-check" tabindex="-1"><span class="hub-section-number">4 </span>Node.js tech-check <a class="header-anchor" href="#node-js-tech-check" aria-label="Permalink to “4 Node.js tech-check”">​</a></h2><p>The <a href="./tech-check/">dedicated tech-check section</a> follows the supplied25 exam-topic groups. It contains a complete subtopic checklist, stable question IDs, spoken answers plus detailed explanations, code/debugging questions and separate batch progress. Runtime fundamentals, CLI/process management, modules and package-management questions are available in completed small batches. The asynchronous-programming questions also cover bounded concurrency, combinators, cancellation and async iteration; Events, event waiting and context-specific event-loop scheduling are also available; OS/libuv boundaries, signal shutdown, loop measurements and starvation diagnosis are now covered too; The first core-API batch covers Console, asynchronous filesystem operations, Path and OS; Buffer ownership, incremental decoding, timers and URL handling are also covered; Streams, readline, crypto and compression complete the core-API question group; The networking section now covers TCP, IP/UDP, HTTPS and DNS; WebSockets, Socket.IO and production transport selection complete the networking question group; later groups stay explicitly planned.</p>',22)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
